document.addEventListener("DOMContentLoaded", () => {
    const capaProvincias = document.getElementById("capa-provincias");
    const estadoSeleccion = document.getElementById("estado-seleccion");
    const nombreProvincia = document.getElementById("nombre-provincia");
    const capitalProvincia = document.getElementById("capital-provincia");
    const habitantesProvincia = document.getElementById("habitantes-provincia");
    const datosDetalle = document.getElementById("datos-detalle");
    const instruccionInicial = document.getElementById("instruccion-inicial");

    const formateadorNumero = new Intl.NumberFormat("es-ES");
    let elementoActivo = null;

    PROVINCIAS.forEach((provincia) => {
        const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
        path.setAttribute("d", provincia.d);
        path.setAttribute("class", "provincia");
        path.setAttribute("data-nombre", provincia.nombre);
        path.setAttribute("tabindex", "0");
        path.setAttribute("role", "button");
        path.setAttribute("aria-label", provincia.nombre);

        const title = document.createElementNS("http://www.w3.org/2000/svg", "title");
        title.textContent = provincia.nombre;
        path.appendChild(title);

        const seleccionar = () => {
            if (elementoActivo) {
                elementoActivo.classList.remove("activa");
            }
            path.classList.add("activa");
            elementoActivo = path;

            estadoSeleccion.textContent = "Provincia seleccionada";
            nombreProvincia.textContent = provincia.nombre;
            capitalProvincia.textContent = provincia.capital;
            habitantesProvincia.textContent = formateadorNumero.format(provincia.habitantes) + " hab.";

            instruccionInicial.hidden = true;
            datosDetalle.hidden = false;
        };

        path.addEventListener("click", seleccionar);
        path.addEventListener("keydown", (evento) => {
            if (evento.key === "Enter" || evento.key === " ") {
                evento.preventDefault();
                seleccionar();
            }
        });

        capaProvincias.appendChild(path);
    });
});
